"""Authored analyst questions over Chinook with gold SQL (the gold result set is computed from it).

Each question names the exact columns to return so result-set equality is a fair test. Questions
with "top N" are checked for ties at the cut-off when the task file is built.
"""

QUESTIONS = [
    # --- harder: definitions the analyst must apply exactly
    ("How many customers spent more in total than the average customer's total spend? Return one column: the count.",
     "WITH s AS (SELECT CustomerId, SUM(Total) t FROM Invoice GROUP BY CustomerId) SELECT COUNT(*) FROM s WHERE t > (SELECT AVG(t) FROM s)"),
    ("For each sales support agent, how many distinct countries do their customers live in? Return columns: agent first name, agent last name, country count.",
     "SELECT e.FirstName, e.LastName, COUNT(DISTINCT c.Country) FROM Employee e JOIN Customer c ON c.SupportRepId = e.EmployeeId GROUP BY e.EmployeeId"),
    ("In 2022, which month had the largest revenue increase over the previous month of 2022? Return columns: month as 'YYYY-MM', increase rounded to 2 decimals.",
     "WITH m AS (SELECT strftime('%Y-%m', InvoiceDate) mo, SUM(Total) r FROM Invoice WHERE strftime('%Y', InvoiceDate) = '2022' GROUP BY mo), d AS (SELECT mo, r - LAG(r) OVER (ORDER BY mo) inc FROM m) SELECT mo, ROUND(inc, 2) FROM d WHERE inc IS NOT NULL ORDER BY inc DESC LIMIT 1"),
    ("Which 3 customers bought tracks by the most distinct artists? Break ties by customer id ascending. Return columns: first name, last name, artist count.",
     "SELECT c.FirstName, c.LastName, COUNT(DISTINCT a.ArtistId) n FROM Customer c JOIN Invoice i ON i.CustomerId = c.CustomerId JOIN InvoiceLine il ON il.InvoiceId = i.InvoiceId JOIN Track t ON il.TrackId = t.TrackId JOIN Album a ON t.AlbumId = a.AlbumId GROUP BY c.CustomerId ORDER BY n DESC, c.CustomerId ASC LIMIT 3"),
    ("How many tracks appear in more than 4 different playlists (count playlists by id, not name)? Return one column: the count.",
     "SELECT COUNT(*) FROM (SELECT TrackId FROM PlaylistTrack GROUP BY TrackId HAVING COUNT(DISTINCT PlaylistId) > 4)"),
    ("What is the average number of invoice lines per invoice, rounded to 2 decimals? Return one column.",
     "SELECT ROUND(CAST(COUNT(*) AS REAL) / (SELECT COUNT(*) FROM Invoice), 2) FROM InvoiceLine"),
    ("Across every playlist named 'Music', which artist has the most distinct tracks? Return columns: artist name, distinct track count.",
     "SELECT r.Name, COUNT(DISTINCT t.TrackId) n FROM Playlist p JOIN PlaylistTrack pt ON pt.PlaylistId = p.PlaylistId JOIN Track t ON t.TrackId = pt.TrackId JOIN Album a ON a.AlbumId = t.AlbumId JOIN Artist r ON r.ArtistId = a.ArtistId WHERE p.Name = 'Music' GROUP BY r.ArtistId ORDER BY n DESC LIMIT 1"),
    ("What percent of total invoice revenue comes from the 10 highest-spending customers? Round to 2 decimals. Return one column.",
     "WITH s AS (SELECT CustomerId, SUM(Total) t FROM Invoice GROUP BY CustomerId ORDER BY t DESC LIMIT 10) SELECT ROUND(100.0 * (SELECT SUM(t) FROM s) / (SELECT SUM(Total) FROM Invoice), 2)"),
    ("In 2025, among billing countries with at least 5 invoices that year, which had the highest average invoice total? Return columns: country, average rounded to 2 decimals.",
     "SELECT BillingCountry, ROUND(AVG(Total), 2) FROM Invoice WHERE strftime('%Y', InvoiceDate) = '2025' GROUP BY BillingCountry HAVING COUNT(*) >= 5 ORDER BY AVG(Total) DESC LIMIT 1"),
    ("How many albums have all of their tracks in a single genre? Return one column: the count.",
     "SELECT COUNT(*) FROM (SELECT AlbumId FROM Track GROUP BY AlbumId HAVING COUNT(DISTINCT GenreId) = 1)"),
    ("Which customer has the most days between their first and last invoice? Return columns: first name, last name, days (integer).",
     "SELECT c.FirstName, c.LastName, CAST(julianday(MAX(i.InvoiceDate)) - julianday(MIN(i.InvoiceDate)) AS INTEGER) d FROM Customer c JOIN Invoice i ON i.CustomerId = c.CustomerId GROUP BY c.CustomerId ORDER BY d DESC LIMIT 1"),
    ("Which 5 artists have the most albums? Return columns: artist name, album count.",
     "SELECT r.Name, COUNT(*) c FROM Album a JOIN Artist r ON a.ArtistId = r.ArtistId GROUP BY r.ArtistId ORDER BY c DESC LIMIT 5"),
    ("For each media type, how many tracks use it? Return columns: media type name, track count.",
     "SELECT m.Name, COUNT(*) FROM Track t JOIN MediaType m ON t.MediaTypeId = m.MediaTypeId GROUP BY m.MediaTypeId"),
    ("What is the total amount spent by the customer named 'Leonie Kohler'? Round to 2 decimals. Return one column.",
     "SELECT ROUND(SUM(i.Total), 2) FROM Invoice i JOIN Customer c ON i.CustomerId = c.CustomerId WHERE c.FirstName = 'Leonie' AND c.LastName = 'Köhler'"),
    ("How many tracks are in the playlist named 'Grunge'? Return one column: the count.",
     "SELECT COUNT(*) FROM PlaylistTrack pt JOIN Playlist p ON pt.PlaylistId = p.PlaylistId WHERE p.Name = 'Grunge'"),
    ("Which customers are supported by the employee 'Jane Peacock'? Return columns: customer first name, customer last name.",
     "SELECT c.FirstName, c.LastName FROM Customer c JOIN Employee e ON c.SupportRepId = e.EmployeeId WHERE e.FirstName = 'Jane' AND e.LastName = 'Peacock'"),
    ("Who does the employee 'Nancy Edwards' report to? Return columns: first name, last name of the manager.",
     "SELECT m.FirstName, m.LastName FROM Employee e JOIN Employee m ON e.ReportsTo = m.EmployeeId WHERE e.FirstName = 'Nancy' AND e.LastName = 'Edwards'"),
    ("List genres that have no tracks sold at all (never appear in an invoice line). Return one column: genre name.",
     "SELECT g.Name FROM Genre g WHERE g.GenreId NOT IN (SELECT t.GenreId FROM InvoiceLine il JOIN Track t ON il.TrackId = t.TrackId WHERE t.GenreId IS NOT NULL)"),
    # --- aggregates with joins
    ("Which 3 countries generated the most revenue (sum of invoice totals by billing country)? Return columns: country, revenue rounded to 2 decimals.",
     "SELECT BillingCountry, ROUND(SUM(Total), 2) r FROM Invoice GROUP BY BillingCountry ORDER BY SUM(Total) DESC LIMIT 3"),
    ("Which sales support agent's customers produced the most invoice revenue? Return columns: agent first name, agent last name, revenue rounded to 2 decimals.",
     "SELECT e.FirstName, e.LastName, ROUND(SUM(i.Total), 2) FROM Invoice i JOIN Customer c ON i.CustomerId = c.CustomerId JOIN Employee e ON c.SupportRepId = e.EmployeeId GROUP BY e.EmployeeId ORDER BY SUM(i.Total) DESC LIMIT 1"),
    ("What are the 5 best-selling tracks by number of units sold (sum of invoice line quantity)? Break ties by track id ascending. Return columns: track name, units sold.",
     "SELECT t.Name, SUM(il.Quantity) u FROM InvoiceLine il JOIN Track t ON il.TrackId = t.TrackId GROUP BY t.TrackId ORDER BY u DESC, t.TrackId ASC LIMIT 5"),
    ("Which genre has the highest total sales revenue (unit price x quantity over invoice lines)? Return columns: genre name, revenue rounded to 2 decimals.",
     "SELECT g.Name, ROUND(SUM(il.UnitPrice * il.Quantity), 2) FROM InvoiceLine il JOIN Track t ON il.TrackId = t.TrackId JOIN Genre g ON t.GenreId = g.GenreId GROUP BY g.GenreId ORDER BY SUM(il.UnitPrice * il.Quantity) DESC LIMIT 1"),
    ("What is the average track length in minutes for each genre with at least 100 tracks, rounded to 2 decimals? Return columns: genre name, average minutes.",
     "SELECT g.Name, ROUND(AVG(t.Milliseconds) / 60000.0, 2) FROM Track t JOIN Genre g ON t.GenreId = g.GenreId GROUP BY g.GenreId HAVING COUNT(*) >= 100"),
    ("For each year, what was the total invoice revenue, rounded to 2 decimals? Return columns: year (as text like '2021'), revenue.",
     "SELECT strftime('%Y', InvoiceDate), ROUND(SUM(Total), 2) FROM Invoice GROUP BY 1"),
    ("Which customer spent the most in total? Return columns: first name, last name, total spent rounded to 2 decimals.",
     "SELECT c.FirstName, c.LastName, ROUND(SUM(i.Total), 2) FROM Invoice i JOIN Customer c ON i.CustomerId = c.CustomerId GROUP BY c.CustomerId ORDER BY SUM(i.Total) DESC LIMIT 1"),
    ("How many distinct customers bought at least one 'Jazz' track? Return one column: the count.",
     "SELECT COUNT(DISTINCT i.CustomerId) FROM Invoice i JOIN InvoiceLine il ON il.InvoiceId = i.InvoiceId JOIN Track t ON il.TrackId = t.TrackId JOIN Genre g ON t.GenreId = g.GenreId WHERE g.Name = 'Jazz'"),
    ("Which albums have more than 25 tracks? Return columns: album title, track count.",
     "SELECT a.Title, COUNT(*) FROM Track t JOIN Album a ON t.AlbumId = a.AlbumId GROUP BY a.AlbumId HAVING COUNT(*) > 25"),
    ("Which artists have at least one track longer than 20 minutes? Return one column: artist name (distinct).",
     "SELECT DISTINCT r.Name FROM Track t JOIN Album a ON t.AlbumId = a.AlbumId JOIN Artist r ON a.ArtistId = r.ArtistId WHERE t.Milliseconds > 1200000"),
    ("What is the average invoice total for customers in the USA, rounded to 2 decimals? Use the customer's country. Return one column.",
     "SELECT ROUND(AVG(i.Total), 2) FROM Invoice i JOIN Customer c ON i.CustomerId = c.CustomerId WHERE c.Country = 'USA'"),
    ("How many tracks have never been purchased? Return one column: the count.",
     "SELECT COUNT(*) FROM Track WHERE TrackId NOT IN (SELECT TrackId FROM InvoiceLine)"),
    # --- harder: subqueries, windows, multi-step
    ("Which month (YYYY-MM) had the highest invoice revenue? Return columns: month, revenue rounded to 2 decimals.",
     "SELECT strftime('%Y-%m', InvoiceDate) m, ROUND(SUM(Total), 2) FROM Invoice GROUP BY m ORDER BY SUM(Total) DESC, m ASC LIMIT 1"),
    ("For each country, which customer spent the most? Only include countries with at least 2 customers. Return columns: country, first name, last name, total rounded to 2 decimals.",
     "WITH s AS (SELECT c.Country, c.FirstName, c.LastName, SUM(i.Total) t FROM Customer c JOIN Invoice i ON i.CustomerId = c.CustomerId GROUP BY c.CustomerId), k AS (SELECT Country FROM Customer GROUP BY Country HAVING COUNT(*) >= 2) SELECT s.Country, s.FirstName, s.LastName, ROUND(s.t, 2) FROM s WHERE s.Country IN (SELECT Country FROM k) AND s.t = (SELECT MAX(t) FROM s s2 WHERE s2.Country = s.Country)"),
    ("Which playlists contain more than 1000 tracks? Return columns: playlist name, track count. (Playlists with the same name count separately.)",
     "SELECT p.Name, COUNT(*) FROM PlaylistTrack pt JOIN Playlist p ON pt.PlaylistId = p.PlaylistId GROUP BY p.PlaylistId HAVING COUNT(*) > 1000"),
    ("What percentage of all invoice-line revenue comes from the 'Rock' genre? Round to 2 decimals. Return one column.",
     "SELECT ROUND(100.0 * SUM(CASE WHEN g.Name = 'Rock' THEN il.UnitPrice * il.Quantity ELSE 0 END) / SUM(il.UnitPrice * il.Quantity), 2) FROM InvoiceLine il JOIN Track t ON il.TrackId = t.TrackId JOIN Genre g ON t.GenreId = g.GenreId"),
    ("List employees who have no one reporting to them. Return columns: first name, last name.",
     "SELECT FirstName, LastName FROM Employee WHERE EmployeeId NOT IN (SELECT ReportsTo FROM Employee WHERE ReportsTo IS NOT NULL)"),
    ("How many customers have made purchases in every year from 2021 to 2025? Return one column: the count.",
     "SELECT COUNT(*) FROM (SELECT CustomerId FROM Invoice WHERE strftime('%Y', InvoiceDate) BETWEEN '2021' AND '2025' GROUP BY CustomerId HAVING COUNT(DISTINCT strftime('%Y', InvoiceDate)) = 5)"),
    ("Which artist earned the most revenue from invoice lines (unit price x quantity)? Return columns: artist name, revenue rounded to 2 decimals.",
     "SELECT r.Name, ROUND(SUM(il.UnitPrice * il.Quantity), 2) FROM InvoiceLine il JOIN Track t ON il.TrackId = t.TrackId JOIN Album a ON t.AlbumId = a.AlbumId JOIN Artist r ON a.ArtistId = r.ArtistId GROUP BY r.ArtistId ORDER BY SUM(il.UnitPrice * il.Quantity) DESC LIMIT 1"),
    ("What is the median invoice total? (With an even count, average the two middle values.) Round to 2 decimals. Return one column.",
     "WITH o AS (SELECT Total, ROW_NUMBER() OVER (ORDER BY Total) rn, COUNT(*) OVER () n FROM Invoice) SELECT ROUND(AVG(Total), 2) FROM o WHERE rn IN ((n + 1) / 2, (n + 2) / 2)"),
    ("Which customers bought tracks from more than 10 distinct genres? Return columns: first name, last name, genre count.",
     "SELECT c.FirstName, c.LastName, COUNT(DISTINCT t.GenreId) FROM Customer c JOIN Invoice i ON i.CustomerId = c.CustomerId JOIN InvoiceLine il ON il.InvoiceId = i.InvoiceId JOIN Track t ON il.TrackId = t.TrackId GROUP BY c.CustomerId HAVING COUNT(DISTINCT t.GenreId) > 10"),
    ("For the year 2024, what share of revenue (percent, 2 decimals) came from customers in the USA (by billing country)? Return one column.",
     "SELECT ROUND(100.0 * SUM(CASE WHEN BillingCountry = 'USA' THEN Total ELSE 0 END) / SUM(Total), 2) FROM Invoice WHERE strftime('%Y', InvoiceDate) = '2024'"),
]

# --- harder questions (business definitions, windows, multi-step). They replace the slots of easier
# ones so the seeded test split carries the hard material.
_HARD = {
    3: ("Loyalty tiers: Gold if a customer's lifetime spend is at least 45, Silver if at least 40, otherwise Bronze. How many customers are in each tier? Return columns: tier, count.",
        "SELECT CASE WHEN t >= 45 THEN 'Gold' WHEN t >= 40 THEN 'Silver' ELSE 'Bronze' END tier, COUNT(*) FROM (SELECT CustomerId, SUM(Total) t FROM Invoice GROUP BY CustomerId) GROUP BY tier"),
    4: ("Net revenue counts invoice lines on media types whose name contains 'Protected' at 50% (they are partly refunded) and all other lines at 100%. Which media type has the highest net revenue? Return columns: media type name, net revenue rounded to 2 decimals.",
        "SELECT m.Name, ROUND(SUM(il.UnitPrice * il.Quantity * CASE WHEN m.Name LIKE '%Protected%' THEN 0.5 ELSE 1 END), 2) r FROM InvoiceLine il JOIN Track t ON t.TrackId = il.TrackId JOIN MediaType m ON m.MediaTypeId = t.MediaTypeId GROUP BY m.MediaTypeId ORDER BY r DESC LIMIT 1"),
    5: ("For each year, which customer spent the most that year (ties broken by the lowest customer id)? Return columns: year as text like '2021', first name, last name, spend rounded to 2 decimals.",
        "WITH s AS (SELECT strftime('%Y', i.InvoiceDate) y, i.CustomerId, SUM(i.Total) t FROM Invoice i GROUP BY y, i.CustomerId), r AS (SELECT y, CustomerId, t, ROW_NUMBER() OVER (PARTITION BY y ORDER BY t DESC, CustomerId ASC) rn FROM s) SELECT r.y, c.FirstName, c.LastName, ROUND(r.t, 2) FROM r JOIN Customer c ON c.CustomerId = r.CustomerId WHERE rn = 1"),
    7: ("Ordering invoices by invoice date then invoice id, on which invoice date does the running total of invoice revenue first exceed 1000? Return one column: the date as 'YYYY-MM-DD'.",
        "WITH r AS (SELECT InvoiceDate, SUM(Total) OVER (ORDER BY InvoiceDate, InvoiceId) c FROM Invoice) SELECT date(InvoiceDate) FROM r WHERE c > 1000 ORDER BY c LIMIT 1"),
    8: ("Among genres with at least 20 units sold in 2022 (by invoice date), which had the largest percentage growth in units sold from 2022 to 2023? Return columns: genre name, growth percent rounded to 2 decimals.",
        "WITH u AS (SELECT t.GenreId g, SUM(CASE WHEN strftime('%Y', i.InvoiceDate) = '2022' THEN il.Quantity ELSE 0 END) a, SUM(CASE WHEN strftime('%Y', i.InvoiceDate) = '2023' THEN il.Quantity ELSE 0 END) b FROM InvoiceLine il JOIN Invoice i ON i.InvoiceId = il.InvoiceId JOIN Track t ON t.TrackId = il.TrackId GROUP BY t.GenreId) SELECT gn.Name, ROUND(100.0 * (b - a) / a, 2) p FROM u JOIN Genre gn ON gn.GenreId = u.g WHERE a >= 20 ORDER BY p DESC LIMIT 1"),
    12: ("How many invoices contain tracks from at least 3 different genres? Return one column: the count.",
         "SELECT COUNT(*) FROM (SELECT il.InvoiceId FROM InvoiceLine il JOIN Track t ON t.TrackId = il.TrackId GROUP BY il.InvoiceId HAVING COUNT(DISTINCT t.GenreId) >= 3)"),
    14: ("For each employee, compute the invoice revenue of the customers they support directly plus the customers supported by their direct reports (one level down). Include only employees with a non-zero result. Return columns: first name, last name, revenue rounded to 2 decimals.",
         "SELECT e.FirstName, e.LastName, ROUND(SUM(i.Total), 2) FROM Employee e JOIN Employee s ON (s.EmployeeId = e.EmployeeId OR s.ReportsTo = e.EmployeeId) JOIN Customer c ON c.SupportRepId = s.EmployeeId JOIN Invoice i ON i.CustomerId = c.CustomerId GROUP BY e.EmployeeId"),
    18: ("For each customer, take the average number of days between their consecutive invoices; then average that over all customers with at least 2 invoices. Round to 2 decimals. Return one column.",
         "WITH g AS (SELECT CustomerId, julianday(InvoiceDate) - julianday(LAG(InvoiceDate) OVER (PARTITION BY CustomerId ORDER BY InvoiceDate, InvoiceId)) d FROM Invoice), c AS (SELECT CustomerId, AVG(d) a FROM g WHERE d IS NOT NULL GROUP BY CustomerId) SELECT ROUND(AVG(a), 2) FROM c"),
    19: ("Which billing country has the second-highest invoice revenue? Return columns: country, revenue rounded to 2 decimals.",
         "SELECT BillingCountry, ROUND(SUM(Total), 2) FROM Invoice GROUP BY BillingCountry ORDER BY SUM(Total) DESC LIMIT 1 OFFSET 1"),
    21: ("How many artists have at least one album, and every one of their albums has at least 10 tracks? Return one column: the count.",
         "WITH al AS (SELECT a.ArtistId, a.AlbumId, COUNT(t.TrackId) n FROM Album a LEFT JOIN Track t ON t.AlbumId = a.AlbumId GROUP BY a.AlbumId) SELECT COUNT(*) FROM (SELECT ArtistId FROM al GROUP BY ArtistId HAVING MIN(n) >= 10)"),
    23: ("How many customers never bought a single 'Jazz' track? Return one column: the count.",
         "SELECT COUNT(*) FROM Customer WHERE CustomerId NOT IN (SELECT i.CustomerId FROM Invoice i JOIN InvoiceLine il ON il.InvoiceId = i.InvoiceId JOIN Track t ON t.TrackId = il.TrackId JOIN Genre g ON g.GenreId = t.GenreId WHERE g.Name = 'Jazz')"),
    29: ("How many distinct track names appear on more than 2 different albums? Return one column: the count.",
         "SELECT COUNT(*) FROM (SELECT Name FROM Track GROUP BY Name HAVING COUNT(DISTINCT AlbumId) > 2)"),
    32: ("What percent of invoice-line revenue (unit price x quantity) comes from tracks with no composer recorded? Round to 2 decimals. Return one column.",
         "SELECT ROUND(100.0 * SUM(CASE WHEN t.Composer IS NULL THEN il.UnitPrice * il.Quantity ELSE 0 END) / SUM(il.UnitPrice * il.Quantity), 2) FROM InvoiceLine il JOIN Track t ON t.TrackId = il.TrackId"),
    34: ("How many distinct countries have at least one customer with a company name recorded? Return one column: the count.",
         "SELECT COUNT(DISTINCT Country) FROM Customer WHERE Company IS NOT NULL AND TRIM(Company) <> ''"),
    36: ("Which calendar quarter had the highest invoice revenue? Return columns: quarter as 'YYYY-Qn' (e.g. '2021-Q3'), revenue rounded to 2 decimals.",
         "SELECT strftime('%Y', InvoiceDate) || '-Q' || ((CAST(strftime('%m', InvoiceDate) AS INTEGER) + 2) / 3) q, ROUND(SUM(Total), 2) FROM Invoice GROUP BY q ORDER BY SUM(Total) DESC LIMIT 1"),
}
for _i, _q in _HARD.items():
    QUESTIONS[_i] = _q
